import{_ as t,o as h,c as a,a2 as c}from"./chunks/framework.62rcL0wY.js";const o="/clickermann-guide-vi/so-do/toa-do.svg",u=JSON.parse('{"title":"Hệ tọa độ màn hình và phần tử","description":"","frontmatter":{},"headers":[],"relativePath":"khai-niem/toa-do.md","filePath":"khai-niem/toa-do.md"}'),i={name:"khai-niem/toa-do.md"};function e(r,n,d,g,m,s){return h(),a("div",null,[...n[0]||(n[0]=[c('<h1 id="he-toa-do-man-hinh-va-phan-tu" tabindex="-1">Hệ tọa độ màn hình và phần tử <a class="header-anchor" href="#he-toa-do-man-hinh-va-phan-tu" aria-label="Permalink to &quot;Hệ tọa độ màn hình và phần tử&quot;">​</a></h1><p>Trang này giải thích cách xác định tọa độ điểm ảnh <code>(x, y)</code> trên màn hình, cách xem tọa độ thực tế trong Trình soạn thảo và sự thay đổi sang hệ tọa độ tương đối khi bật chế độ khóa cửa sổ.</p><h2 id="toa-do-tuyet-doi-tren-man-hinh" tabindex="-1">Tọa độ tuyệt đối trên màn hình <a class="header-anchor" href="#toa-do-tuyet-doi-tren-man-hinh" aria-label="Permalink to &quot;Tọa độ tuyệt đối trên màn hình&quot;">​</a></h2><p>Màn hình máy tính là một lưới hình chữ nhật gồm các điểm ảnh:</p><ul><li>Điểm ảnh ở <strong>góc trái trên cùng</strong> của màn hình luôn có tọa độ là <strong><code>(0, 0)</code></strong>.</li><li>Trục hoành <strong><code>X</code></strong> tăng dần từ trái sang phải.</li><li>Trục tung <strong><code>Y</code></strong> tăng dần từ trên xuống dưới.</li><li>Nếu màn hình của bạn có độ phân giải <code>800×600</code>, điểm ảnh ở góc phải dưới cùng sẽ có tọa độ là <code>(799, 599)</code>.</li><li>Khi dùng nhiều màn hình ghép nối (Extended Desktop), Clickermann hỗ trợ đầy đủ cả tọa độ dương lẫn tọa độ âm.</li></ul><p><strong>Cách lấy tọa độ của một điểm trên màn hình:</strong> Bạn hãy mở cửa sổ <a href="/clickermann-guide-vi/bat-dau/trinh-soan-thao.html">Trình soạn thảo</a> và di chuyển con trỏ chuột tới vị trí cần lấy trên màn hình; tọa độ <code>X</code>, <code>Y</code> tại đầu mũi chuột sẽ hiện liên tục ở khung thông tin cột bên trái. Bạn có thể nhấn phím tắt <strong><code>Alt + Q</code></strong> để chèn nhanh tọa độ (kèm mã màu) tại vị trí chuột vào thẳng dòng lệnh trong trình soạn thảo.</p><p><img src="'+o+'" alt="So sánh hệ tọa độ màn hình và hệ tọa độ tương đối của phần tử đang khóa"></p><h2 id="toa-do-tuong-doi-cua-phan-tu-dang-khoa" tabindex="-1">Tọa độ tương đối của phần tử đang khóa <a class="header-anchor" href="#toa-do-tuong-doi-cua-phan-tu-dang-khoa" aria-label="Permalink to &quot;Tọa độ tương đối của phần tử đang khóa&quot;">​</a></h2><p>Khi bạn bật <strong>chế độ khóa cửa sổ</strong> (<code>Alt + W</code> hoặc lệnh <a href="/clickermann-guide-vi/lenh/winapi.html#hset"><code>HSET</code></a>), hệ tọa độ trong cả trình soạn thảo lẫn khi chạy script sẽ tự động chuyển sang <strong>hệ tọa độ tương đối của phần tử đang khóa</strong>:</p><ul><li>Gốc tọa độ <strong><code>(0, 0)</code></strong> lúc này nằm tại <strong>góc trái trên cùng của chính phần tử đang khóa</strong> (không còn là góc trái trên của màn hình nền).</li><li>Hệ tọa độ này được gọi là <em>tương đối</em> vì ngay cả khi bạn kéo cửa sổ ứng dụng đi chỗ khác trên màn hình, tọa độ nội bộ của các điểm bên trong phần tử đó vẫn giữ nguyên không đổi.</li></ul><h2 id="cac-bien-he-thong-gioi-han-toa-do-xmax-ymax-xmin-ymin" tabindex="-1">Các biến hệ thống giới hạn tọa độ (<code>$_xmax</code>, <code>$_ymax</code>, <code>$_xmin</code>, <code>$_ymin</code>) <a class="header-anchor" href="#cac-bien-he-thong-gioi-han-toa-do-xmax-ymax-xmin-ymin" aria-label="Permalink to &quot;Các biến hệ thống giới hạn tọa độ (`$_xmax`, `$_ymax`, `$_xmin`, `$_ymin`)&quot;">​</a></h2><p>Trong bảng biến hệ thống, Clickermann cung cấp các biến <code>$_xmax</code>, <code>$_ymax</code>, <code>$_xmin</code> và <code>$_ymin</code>:</p><ul><li>🟠 <strong>Lưu ý khi dùng <code>$_xmax</code>, <code>$_ymax</code>, <code>$_xmin</code>, <code>$_ymin</code>:</strong><ul><li><strong>Nên làm:</strong> Ở chế độ thường toàn màn hình, bạn có thể dùng <code>0, 0, $_xmax, $_ymax</code> để quét toàn màn hình. Khi đang bật khóa cửa sổ vào một cửa sổ nhỏ, hãy in thử giá trị của chúng bằng <code>PRINT($_xmin, &quot;, &quot;, $_ymin, &quot; -&gt; &quot;, $_xmax, &quot;, &quot;, $_ymax)</code> hoặc điền trực tiếp tọa độ vùng cần quét.</li></ul><details class="details custom-block"><summary>Vì sao chưa chắc</summary><ul><li><strong>Theo help (phần Giới thiệu ngôn ngữ):</strong> <code>$_xmax</code>, <code>$_ymax</code>, <code>$_xmin</code>, <code>$_ymin</code> là giá trị tọa độ X, Y lớn nhất và nhỏ nhất cho phép, được <strong>tính từ cấu hình màn hình desktop</strong>.</li><li><strong>Theo sách của Chô tô (tr. 26):</strong> Ghi rằng <code>$_xmax</code>, <code>$_ymax</code> là <strong>tọa độ lớn nhất của cửa sổ</strong>, còn <code>$_xmin</code>, <code>$_ymin</code> là <strong>tọa độ nhỏ nhất (ở góc trái trên) của cửa sổ</strong>.</li><li>Suy luận: ở chế độ thường một màn hình thì hai cách nói cho kết quả gần giống nhau, nhưng khi đang bật chế độ khóa cửa sổ vào một cửa sổ nhỏ thì hai cách hiểu này sẽ khác nhau. Xem script kiểm chứng tại <a href="/clickermann-guide-vi/phu-luc/can-kiem-tra-tren-windows.html#gia-tri-cua-xmax-va-ymax-khi-khoa-cua-so">Cần kiểm tra trên Windows</a>.</li></ul></details></li></ul><hr><p><em>Nguồn: Tài liệu trợ giúp <code>help.chm</code> (mục Màn hình, bài Khóa cửa sổ, phần Giới thiệu ngôn ngữ và FAQ); tham khảo đối chiếu sách của Chô tô (tr. 26).</em></p>',15)])])}const p=t(i,[["render",e]]);export{u as __pageData,p as default};
